\set ON_ERROR_STOP on
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL statement_timeout='60s'; SET LOCAL lock_timeout='2s'; SET LOCAL timezone='UTC';
DO $g$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' OR inet_client_addr() IS NOT NULL OR current_database()<>'verdify_rehearsal' OR current_setting('cluster_name')<>'verdify-cnpg-s2-integration' OR pg_is_in_recovery() OR current_setting('server_version_num')::int<>160013 OR (SELECT oid FROM pg_database WHERE datname=current_database())<>16447 OR (SELECT system_identifier::text FROM pg_control_system())<>'7693399121498484768' THEN RAISE EXCEPTION '382 native witness authority refused'; END IF; END $g$;
SELECT jsonb_build_object('kind','roles','roles',jsonb_agg(jsonb_build_object('role',r.rolname,'login',r.rolcanlogin,'password_null',r.rolpassword IS NULL,'super',r.rolsuper,'create_db',r.rolcreatedb,'create_role',r.rolcreaterole,'replication',r.rolreplication,'bypass_rls',r.rolbypassrls,'memberships',(SELECT jsonb_agg(p.rolname ORDER BY p.rolname) FROM pg_auth_members a JOIN pg_roles p ON p.oid=a.roleid WHERE a.member=r.oid)) ORDER BY r.rolname)) FROM pg_authid r WHERE rolname IN ('verdify_ingestor_runtime_login','verdify_experiment_v2_equipment_source_collector_login');
SELECT jsonb_build_object('kind','ledger','table','climate_source_events','count',count(*),'whole_row_sha256',jsonb_agg(encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex') ORDER BY event_id),'runtime_receipt_count',(SELECT count(*) FROM public.climate_source_events WHERE source_runtime_instance_id='f4d61647-6648-4d8d-a19a-802e07638a7c'::uuid)) FROM public.climate_source_events t WHERE event_id='4cc32461-2d38-402e-a97a-75105d9694ce'::uuid;
SELECT jsonb_build_object('kind','ledger','table','observational_source_events','count',count(*),'whole_row_sha256',jsonb_agg(encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex') ORDER BY event_id),'runtime_receipt_count',(SELECT count(*) FROM public.observational_source_events WHERE source_runtime_instance_id='f4d61647-6648-4d8d-a19a-802e07638a7c'::uuid)) FROM public.observational_source_events t WHERE event_id='24e3fbd7-43b2-4676-9873-5ac888db7484'::uuid;
SELECT jsonb_build_object('kind','ledger','table','equipment_state_source_receipts','count',count(*),'whole_row_sha256',jsonb_agg(encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex') ORDER BY receipt_id),'runtime_receipt_count',(SELECT count(*) FROM public.equipment_state_source_receipts WHERE source_runtime_instance_id='f4d61647-6648-4d8d-a19a-802e07638a7c'::uuid)) FROM public.equipment_state_source_receipts t WHERE receipt_id='e386f4fe-4c90-42b1-a954-0996ed009304'::uuid;
SELECT jsonb_build_object('kind','telemetry','table','climate','count',count(*),'whole_row_sha256',jsonb_agg(encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex'))) FROM public.climate t WHERE ts='2000-01-01T00:00:00.168626+00:00'::timestamptz;
SELECT jsonb_build_object('kind','telemetry','table','diagnostics','count',count(*),'whole_row_sha256',jsonb_agg(encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex'))) FROM public.diagnostics t WHERE ts='2000-01-01T00:00:00.168626+00:00'::timestamptz;
SELECT jsonb_build_object('kind','telemetry','table','equipment_state','count',count(*),'whole_row_sha256',jsonb_agg(encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex'))) FROM public.equipment_state t WHERE ts='2000-01-01T00:00:00.168626+00:00'::timestamptz;
SELECT jsonb_build_object('kind','lineage','table','climate_source_events','rows',jsonb_agg(jsonb_build_object('source_time',source_ts,'runtime',source_runtime_instance_id,'generation',source_connection_generation,'greenhouse_id',greenhouse_id,'fixture_payload',climate_payload))) FROM public.climate_source_events WHERE event_id='4cc32461-2d38-402e-a97a-75105d9694ce'::uuid;
SELECT jsonb_build_object('kind','lineage','table','observational_source_events','rows',jsonb_agg(jsonb_build_object('source_time',source_ts,'runtime',source_runtime_instance_id,'generation',source_connection_generation,'greenhouse_id',greenhouse_id,'fixture_payload',event_payload))) FROM public.observational_source_events WHERE event_id='24e3fbd7-43b2-4676-9873-5ac888db7484'::uuid;
SELECT jsonb_build_object('kind','equipment_metadata','rows',jsonb_agg(jsonb_build_object('source_time',source_observed_through,'runtime',source_runtime_instance_id,'generation',source_connection_generation,'source_sequence',source_sequence,'previous_null',previous_receipt_sha256 IS NULL,'gap_requested',gap_requested,'gap_before',gap_before,'gap_reason',gap_reason,'event_count',event_count,'firmware_revision',firmware_revision))) FROM public.equipment_state_source_receipts WHERE receipt_id='e386f4fe-4c90-42b1-a954-0996ed009304'::uuid;
SELECT jsonb_build_object('kind','frozen_bundle_receipt_references','count',count(*)) FROM public.experiment_v2_outcome_source_bindings WHERE jsonb_path_exists(convert_from(source_bundle_canonical,'UTF8')::jsonb,'$.**.receipt_id ? (@ == $receipt)',jsonb_build_object('receipt','e386f4fe-4c90-42b1-a954-0996ed009304'::text)) OR jsonb_path_exists(convert_from(source_bundle_canonical,'UTF8')::jsonb,'$.**.source_receipt_id ? (@ == $receipt)',jsonb_build_object('receipt','e386f4fe-4c90-42b1-a954-0996ed009304'::text));
SELECT jsonb_build_object('kind','year2000_chunks','chunks',coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.hypertable_name,c.chunk_schema,c.chunk_name),'[]'::jsonb)) FROM timescaledb_information.chunks c WHERE hypertable_schema='public' AND hypertable_name IN ('climate','diagnostics','equipment_state') AND range_start<'2000-02-01'::timestamptz AND range_end>'1999-12-01'::timestamptz;
SELECT jsonb_build_object('kind','immutable_trigger','enabled',tgenabled,'function_sha256',encode(sha256(convert_to(pg_get_functiondef(tgfoid),'UTF8')),'hex')) FROM pg_trigger WHERE tgrelid='public.equipment_state_source_receipts'::regclass AND tgname='trg_equipment_state_source_receipts_immutable';
COMMIT;
